connect.lines:
with fetch: http GET https://credit.internal.example/score | url=https://credit.internal.example/score | resultVariable=score
with reject: http POST https://credit.internal.example/reject | url=https://credit.internal.example/reject | body=={"score": score, "applicantId": applicantId}
with accept: http POST https://credit.internal.example/accept | url=https://credit.internal.example/accept | body=={"score": score, "applicantId": applicantId}

