connect.lines:
with start: webhook-message-start | inbound.context | inbound.method=POST | resultVariable=inbound.body
with stock: http GET https://api.example.com/inventory/check | queryParameters=={orderId: inbound.body.orderId} | authentication.type=apiKey | authentication.apiKeyLocation=header | authentication.name=Authorization | authentication.value={{secrets.API_KEY}}
with team: teams sendMessageToChannel | authentication.credentials.clientId={{secrets.TEAMS_CLIENT_ID}} | authentication.credentials.tenantId={{secrets.TEAMS_TENANT_ID}} | authentication.credentials.clientSecret={{secrets.TEAMS_CLIENT_SECRET}} | data.sendMessageToChannel.groupId={{secrets.TEAMS_GROUP_ID}} | data.sendMessageToChannel.channelId={{secrets.TEAMS_CHANNEL_ID}} | data.sendMessageToChannel.content=="Stock check for order " + inbound.body.orderId + ": " + stock.status

connect.raw:
with start: webhook-message-start | inbound.context | inbound.method=POST | resultVariable=inbound.body
with stock: http GET https://api.example.com/inventory/check | queryParameters=={orderId: inbound.body.orderId} | authentication.type=apiKey | authentication.apiKeyLocation=header | authentication.name=Authorization | authentication.value={{secrets.API_KEY}}
with team: teams sendMessageToChannel | authentication.credentials.clientId={{secrets.TEAMS_CLIENT_ID}} | authentication.credentials.tenantId={{secrets.TEAMS_TENANT_ID}} | authentication.credentials.clientSecret={{secrets.TEAMS_CLIENT_SECRET}} | data.sendMessageToChannel.groupId={{secrets.TEAMS_GROUP_ID}} | data.sendMessageToChannel.channelId={{secrets.TEAMS_CHANNEL_ID}} | data.sendMessageToChannel.content=="Stock check for order " + inbound.body.orderId + ": " + stock.status
